        UNION -->|"Exclude&lt;T, null | undefined&gt;"| R1["string | number"]
        UNION -->|"Extract&lt;T, string&gt;"| R2["string"]
        UNION -->|"NonNullable&lt;T&gt;"| R3["string | number"]
